def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def_total = 0
    my_def_total = 0
    for a, o in history:
        if o == 'D':
            opp_def_total += 1
        if a == 'D':
            my_def_total += 1

    # Mode 3: opponent has defected at least once
    if opp_def_total > 0:
        if n >= 98:
            return 'D'
        if opp_def_total >= 3 and opp_def_total >= n // 2:
            return 'D'
        if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
        return 'C'

    # Mode 4: opponent has never defected
    if my_def_total == 0:
        if n < 10:
            return 'C'
        if n == 10:
            return 'D'
        if n == 11:
            return 'C'

    # Exploitation mode
    if n < 30:
        if n >= 12 and n % 3 == 0:
            return 'D'
        return 'C'

    if n == 30 or n == 31:
        return 'D'
    if n == 32:
        return 'C'

    # After n=32, if opponent still hasn't defected, we passed the double-D test.
    return 'D'
